    'faq' => [
        ['q' => 'Intervenez-vous au Burkina Faso, et faut-il se rencontrer ?', 'r' => 'Oui, à distance. Richard SALANON est à Cotonou ; il a déjà travaillé avec des entreprises au Burkina Faso. Le cadrage, le suivi et la formation se font par visioconférence et par WhatsApp, avec une heure de décalage, sans déplacement.'],
        ['q' => 'Qui doit émettre des factures électroniques certifiées ?', 'r' => 'Selon l\'article 564-2 du Code général des impôts, rappelé par un communiqué de la DGI et de la CCI-BF, les contribuables de la DGE et des DME. L\'obligation est en vigueur depuis le 1er janvier 2025 ; la vente des systèmes de facturation commence le 7 septembre 2026 pour la DGE, le 2 novembre pour le réel normal des DME et le 1er décembre pour leur régime non déterminé.'],
        ['q' => 'Un site doit-il être déclaré à la CIL ?', 'r' => 'Un traitement de données personnelles relève en principe de la déclaration normale (article 27 de la loi 001-2021/AN), sauf exemption ou régime d\'autorisation. Un formulaire de contact, une boutique ou un fichier clients sont concernés. Vérifiez votre cas sur le site de la CIL ou auprès d\'un juriste.'],
        ['q' => 'Peut-on héberger les données de l\'entreprise à l\'étranger ?', 'r' => 'Cela dépend des données. Les données de santé identifiantes doivent être hébergées sur le territoire national sauf dérogation (article 37). Tout transfert vers un pays étranger exige l\'autorisation de la CIL, une clause de confidentialité et une clause de réversibilité (articles 31 et 42).'],
        ['q' => 'Quels portefeuilles mobiles peut-on accepter ?', 'r' => 'Orange Money et Moov Money, par un agrégateur comme LigdiCash ou par un contrat direct. Un site accepte les deux portefeuilles pour ne pas écarter les clients d\'un opérateur. Les frais et les délais se négocient et se fixent par écrit avant l\'intégration.'],
        ['q' => 'Le Burkina Faso est-il toujours dans la zone franc CFA ?', 'r' => 'La page de la BCEAO consultée le 6 octobre 2026 le liste parmi les membres de l\'UMOA. Le retrait de la CEDEAO est effectif depuis le 29 janvier 2025, selon le communiqué de la CEDEAO. Les devis restent en FCFA, et la page sera mise à jour si l\'un de ces faits change.'],
        ['q' => 'La TVA s\'applique-t-elle aux services numériques ?', 'r' => 'Le taux est de 18 %. Depuis le 1er janvier 2025, la TVA est collectée sur les ventes réalisées par des plateformes, y compris celles de prestataires non établis au Burkina Faso, selon la DGI citée par Agence Ecofin le 13 janvier 2025. Votre expert-comptable précise le traitement de chaque facture.'],
        ['q' => 'La formation peut-elle être financée par le FAFPA ?', 'r' => 'Le FAFPA, fonds public, finance des plans de formation d\'entreprises, d\'après Sidwaya. Les conditions actuelles, notamment pour un prestataire établi à l\'étranger, se confirment auprès du fonds avant de s\'engager. À défaut, la formation se finance sur le budget de l\'entreprise.'],
        ['q' => 'Dans quelle devise sont établis les devis ?', 'r' => 'En FCFA, après un cadrage gratuit. Les prix de départ publiés sont de 150 000 FCFA pour une landing page, 300 000 FCFA pour un site vitrine et 75 000 FCFA pour le référencement naturel, soit environ 228,67, 457,35 et 114,34 euros à 655,957 FCFA pour 1 euro.'],
        ['q' => 'Quels délais prévoir pour un site ou une application ?', 'r' => 'Comptez 1 à 3 semaines pour un site vitrine et 1 à 3 mois pour une application sur mesure, selon le périmètre et la rapidité de vos validations. Le raccordement au paiement mobile et à la facture certifiée est planifié dans ce délai.'],
